statement.tex:
\begin{enumerate}
  \item 等差数列 $\{a_n\}$ の初項から第 $n$ 項までの和を $S_n$ とする．$S_5=35,\ S_{10}=20$ のとき，初項と公差を求めよ．
  \item 等差数列で，相異なる自然数 $m,n$ について $S_m=n,\ S_n=m$ が成り立つとき，$S_{m+n}=-(m+n)$ であることを示せ．
\end{enumerate}

初項50，公差 $-3$ の等差数列の初項から第 $n$ 項までの和を $S_n$ とする．
\begin{enumerate}
  \item $S_n$ の最大値と，そのときの $n$ を求めよ．
  \item $S_n<0$ となる最小の $n$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 等比数列で，初項から第 $n$ 項までの和が10，初項から第 $2n$ 項までの和が30のとき，初項から第 $3n$ 項までの和を求めよ．
  \item $\displaystyle\sum_{k=1}^nk\cdot2^k$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $\displaystyle\sum_{k=1}^n\frac{1}{(2k-1)(2k+1)(2k+3)}$ を求めよ．
  \item $\displaystyle\sum_{k=1}^nk(k+1)(k+2)(k+3)$ を求めよ．
  \item $\displaystyle\sum_{k=1}^{99}\frac{1}{\sqrt k+\sqrt{k+1}}$ を求めよ．
\end{enumerate}

数列 $\dfrac11,\ \dfrac12,\ \dfrac22,\ \dfrac13,\ \dfrac23,\ \dfrac33,\ \dfrac14,\ \dfrac24,\ \cdots$（分母 $m$ の群に $\frac1m,\frac2m,\dots,\frac mm$ が並ぶ．約分はしない）について，
\begin{enumerate}
  \item $\dfrac5{12}$ は第何項か．
  \item 第100項を求めよ．
  \item 初項から第100項までの和を求めよ．
\end{enumerate}

自然数を次のように並べる：第1行に1，第2行に2，3，第3行に4，5，6，…（第 $n$ 行には $n$ 個）．
\begin{enumerate}
  \item 第 $n$ 行の最初の数を求めよ．
  \item 2026 は第何行の左から何番目か．
  \item 第 $n$ 行に並ぶ数の和を求めよ．
\end{enumerate}

次の数列の一般項を求めよ．
\begin{enumerate}
  \item $a_1=1,\ a_{n+1}=a_n+2^n+n$
  \item $a_1=1,\ (n+1)a_{n+1}=na_n+2$
\end{enumerate}

次の数列の一般項を求めよ．
\begin{enumerate}
  \item $a_1=1,\ a_{n+1}=3a_n-4$
  \item $a_1=2,\ a_{n+1}=4a_n^{\,3}$
\end{enumerate}

次の数列の一般項を求めよ．
\begin{enumerate}
  \item $a_1=1,\ a_{n+1}=2a_n+3^n$
  \item $a_1=3,\ a_{n+1}=2a_n-n+1$
\end{enumerate}

次の条件を満たす数列 $\{a_n\}$ の一般項を求めよ．$S_n$ は初項から第 $n$ 項までの和とする．
\begin{enumerate}
  \item $S_n=2a_n-n$
  \item $a_1=1,\ S_n=n^2a_n$
\end{enumerate}

次の数列の一般項を求めよ．
\begin{enumerate}
  \item $a_1=1,\ a_2=3,\ a_{n+2}=4a_{n+1}-4a_n$
  \item $a_1=0,\ a_2=1,\ a_{n+2}=a_{n+1}+2a_n$
\end{enumerate}

次の数列の一般項を求めよ．
\begin{enumerate}
  \item $a_1=1,\ a_{n+1}=\dfrac{a_n}{2a_n+1}$
  \item $a_1=3,\ a_{n+1}=\dfrac{3a_n-4}{a_n-1}$
\end{enumerate}

$a_1=b_1=1$，$a_{n+1}=a_n+4b_n$，$b_{n+1}=a_n+b_n$ で定められる数列 $\{a_n\},\{b_n\}$ について，
\begin{enumerate}
  \item $a_{n+1}+pb_{n+1}=q(a_n+pb_n)$ がすべての $n$ で成り立つような定数の組 $(p,q)$ を2組求めよ．
  \item $a_n,\ b_n$ を求めよ．
\end{enumerate}

自然数 $n$ に対し，整数 $a_n,b_n$ を $(1+\sqrt2)^n=a_n+b_n\sqrt2$ で定める．
\begin{enumerate}
  \item $a_{n+1},\ b_{n+1}$ を $a_n,\ b_n$ で表せ．
  \item $a_n^2-2b_n^2=(-1)^n$ を数学的帰納法で示せ．
  \item $|a_n-b_n\sqrt2|=(\sqrt2-1)^n$ を示せ．
\end{enumerate}

$a_1=1,\ a_2=2,\ a_{n+2}=a_{n+1}+a_n$ で定められる数列について，
\begin{enumerate}
  \item $a_3,\dots,a_6$ を求めよ．
  \item すべての自然数 $n$ について $a_n<\Bigl(\dfrac74\Bigr)^n$ が成り立つことを示せ．
\end{enumerate}

\begin{enumerate}
  \item $1,2,\dots,n$ から異なる2つを選んでつくる積の総和を求めよ（$n\geqq2$）．
  \item $1,2,2^2,\dots,2^{n-1}$ から異なる2つを選んでつくる積の総和を求めよ．
\end{enumerate}

\begin{enumerate}
  \item すべての自然数 $n$ について $\displaystyle\sum_{k=1}^n\frac1{k^2}\leqq2-\frac1n$ を示せ．
  \item $0<x_k<1\ (k=1,\dots,n)$ のとき，$(1-x_1)(1-x_2)\cdots(1-x_n)\geqq1-(x_1+x_2+\cdots+x_n)$ を示せ．
\end{enumerate}

$n$ を自然数とする．
\begin{enumerate}
  \item $|x|+2|y|\leqq2n$ を満たす整数の組 $(x,y)$ の個数を求めよ．
  \item $|x|+|y|+|z|\leqq n$ を満たす整数の組 $(x,y,z)$ の個数を求めよ．
\end{enumerate}

数列 $\{a_n\}$ の初項から第 $n$ 項までの和を $S_n$ とする．$S_n=2a_n+n^2$ が成り立つとき，
\begin{enumerate}
  \item $a_1$ と $a_2$ を求めよ．
  \item $a_{n+1}$ を $a_n$ と $n$ を用いて表せ．
  \item $a_n$ と $S_n$ を $n$ の式で表せ．
\end{enumerate}

数列 $3,8,15,24,35,\cdots$ について，
\begin{enumerate}
  \item 第 $n$ 項 $a_n$ と，初項から第 $n$ 項までの和 $S_n$ を求めよ．
  \item $\displaystyle\sum_{k=1}^n\frac1{a_k}$ を求めよ．
  \item $\displaystyle\sum_{k=1}^n\frac{2k+3}{a_ka_{k+1}}$ を求めよ．
\end{enumerate}

年齢1の1つの個体から始めて，次の操作1，2を $n$ 回おこなった後の全個体の年齢の合計を $S_n$ とする．
\begin{itemize}
  \item 操作1．年齢1の各個体から年齢0の $k$ 個の個体を発生させる（$k>1$）．
  \item 操作2．全個体の年齢をそれぞれ1増やす．
\end{itemize}
\begin{enumerate}
  \item $k=3$ のとき $S_3$ を求めよ．
  \item $S_n$ を $k,n$ で表せ．
  \item $n$ 回おこなった後の平均年齢を $A_n$ とするとき，$\displaystyle\lim_{n\to\infty}A_n$ を求めよ．
\end{enumerate}

$a_1=1$，$a_{n+1}=\dfrac{a_n}{3a_n+2}$ で定まる数列 $\{a_n\}$ について，
\begin{enumerate}
  \item $\dfrac1{a_n}$ を $n$ の式で表せ．
  \item $\displaystyle\sum_{k=1}^n\frac1{a_k}$ を $n$ の式で表せ．
\end{enumerate}

[A] $a_1=5$，$a_{n+1}=2a_n+3^n$ を満たす数列について，$b_n=a_n-3^n$ とおく．$b_{n+1}$ を $b_n$ で表し，$a_n$ を求めよ．

[B] $a_1=2$，$a_{n+1}=2a_n-n^2+2$ で定められる数列 $\{a_n\}$ について，
\begin{enumerate}
  \item $b_n=a_n-(\alpha n^2+\beta n+\gamma)$ が等比数列になるように定数 $\alpha,\beta,\gamma$ を定めよ．
  \item 一般項 $a_n$ と，初項から第 $n$ 項までの和 $S_n$ を求めよ．
\end{enumerate}

$x_1=1$，$y_1=1$，$x_{n+1}=2x_n+y_n$，$y_{n+1}=3x_n+4y_n$ で定められる数列 $\{x_n\},\{y_n\}$ について，
\begin{enumerate}
  \item $a_n=x_n+cy_n$ が等比数列となるような定数 $c$ の値をすべて求め，それぞれの場合に $a_n$ を求めよ．
  \item $x_n$ および $y_n$ を $n$ の式で表せ．
\end{enumerate}

\begin{enumerate}
  \item すべての自然数 $n$ に対し，$5^{2n}-24n-1$ は $576$ で割り切れることを示せ．
  \item $5^{100}$ を $576$ で割った余りを求めよ．
\end{enumerate}

\begin{enumerate}
  \item $k\geqq3$ のとき $k!\geqq2\cdot3^{k-2}$ を示せ．
  \item すべての自然数 $n$ に対して $\displaystyle\sum_{k=0}^n\frac1{k!}<\frac{11}4$ を示せ．（$0!=1$）
\end{enumerate}

数列 $a_0,a_1,a_2,\cdots$ を $a_0=\dfrac13$，$a_{n+1}=\dfrac1{n+1}\displaystyle\sum_{k=0}^na_ka_{n-k}$ で定める．
\begin{enumerate}
  \item $a_1,a_2,a_3$ を求めよ．
  \item 一般項 $a_n$ を推測し，それが正しいことを証明せよ．
  \item $b_n=\displaystyle\sum_{k=0}^n\frac{n!}{k!(n-k)!}a_ka_{n-k}$ を求め，$\displaystyle\sum_{n=0}^\infty b_n$ を求めよ．
\end{enumerate}

実数 $x$ に対し $[x]$ を $x$ 以下の最大の整数とする．$a_k=\Bigl[\dfrac{5k}7\Bigr]\ (k=1,2,\cdots)$ と定める．
\begin{enumerate}
  \item $a_1,\cdots,a_7$ を求めよ．
  \item $a_{k+7}=a_k+5$ を示せ．
  \item 自然数 $n$ に対して $\displaystyle\sum_{k=1}^{7n}a_k$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 自然数 $k$ に対し，$x$ の整式 $(1+x+x^2)^k$ における $x^2$ の係数を求めよ．
  \item $\displaystyle\sum_{k=1}^n(1+x+x^2)^k$ における $x^2$ の係数を $a_n$ とする．$a_n$ を求めよ．
  \item $S_n=\dfrac1{a_1}+\dfrac1{a_2}+\cdots+\dfrac1{a_n}$ を求めよ．
\end{enumerate}

各項が正である数列 $\{a_n\}$ を次で定める．
(i) $a_1=1$．\ (ii) 点 $(0,-a_n)$ から放物線の一部 $C:y=2x^2\ (x\geqq0)$ に接線を引き，接点を A$_n$ とする．A$_n$ において接線と直交する直線を引き，$y$ 軸との交点を $(0,2a_{n+1})$ とする．
\begin{enumerate}
  \item $a_n$ と $a_{n+1}$ の関係式を求めよ．
  \item $a_n$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $k$ を0以上の整数とするとき，$\dfrac x2+\dfrac y3\leqq k$ を満たす0以上の整数 $x,y$ の組の個数 $a_k$ を求めよ．
  \item $n$ を0以上の整数とするとき，$\dfrac x2+\dfrac y3+z\leqq n$ を満たす0以上の整数の組 $(x,y,z)$ の個数 $b_n$ を求めよ．
\end{enumerate}

正の整数 $k$ に対し，$a_k$ を $\sqrt k$ にもっとも近い整数とする．
\begin{enumerate}
  \item $a_k=j$ となる $k$ の範囲を求めよ．
  \item $\displaystyle\sum_{k=1}^{12}\frac1{a_k}$，$\displaystyle\sum_{k=1}^{2020}\frac1{a_k}$ を求めよ．
\end{enumerate}

$C_0$ は $(0,1)$ を中心とする半径1の円，$C_1$ は $(2,1)$ を中心とする半径1の円とする．$n=2,3,\dots$ に対し，順に，$C_0$，$C_{n-1}$ に外接し $x$ 軸に接する円で $C_{n-2}$ でないものを $C_n$ とする．$C_n\ (n\geqq1)$ の中心を $(a_n,b_n)$ とする．
\begin{enumerate}
  \item $n\geqq1$ に対し $b_n=\dfrac{a_n^2}4$ を示せ．
  \item $a_n$ を求めよ．
\end{enumerate}

$a_1=1$，$b_1=4$，$a_{n+1}=3a_n+b_n$，$b_{n+1}=2a_n+2b_n$ で数列を定める．
\begin{enumerate}
  \item $a_{n+1}+tb_{n+1}=k(a_n+tb_n)$ がすべての $n$ で成り立つ $(t,k)$ を2組求めよ．
  \item $a_n,b_n$ を $n$ で表せ．
  \item $a_n$ が7で割り切れるための $n$ の条件を求めよ．
\end{enumerate}

$a_1=1$，$a_{n+1}=\dfrac4n(a_1+a_2+\cdots+a_n)\ (n\geqq1)$ で数列 $\{a_n\}$ を定める．
\begin{enumerate}
  \item $a_1,\dots,a_5$ を求め，一般項 $a_n$ を推測せよ．
  \item (1) の推測が正しいことを数学的帰納法で示せ．
\end{enumerate}

2次方程式 $x^2-2x-1=0$ の解を $\alpha,\beta\ (\alpha>\beta)$ とし，$L_n=\alpha^n+\beta^n$ とする．
\begin{enumerate}
  \item $L_n$ はすべての $n\geqq0$ で偶数であることを示せ．
  \item $n\geqq1$ のとき $L_n=\Bigl[\alpha^n+\dfrac12\Bigr]$ を示せ．
  \item $\alpha^n$ の小数部分を $\beta$ を用いて表し，$\displaystyle\lim_{m\to\infty}(\alpha^{2m}\text{ の小数部分})$ を求めよ．
\end{enumerate}

すべての項が正である数列 $\{a_n\}$ に対し $S_n=\sum_{k=1}^na_k$，$T_n=\sum_{k=1}^n\dfrac1{a_k}$，$U_n=\sum_{k=1}^na_k^2$ とおく．
\begin{enumerate}
  \item $S_nT_n\geqq n^2$ を示せ．
  \item $S_n^2\leqq nU_n$ を示せ．
  \item $S_n=n$ のとき，$T_n\geqq n$ かつ $U_n\geqq n$ を示せ．
\end{enumerate}

\begin{enumerate}
  \item $\displaystyle S=\sum_{k=1}^n3^{k-1}(2k+1)$ を $n$ の式で表せ．
  \item $\displaystyle\sum_{j=1}^nj\cdot2^{n-j}$ を求めよ．
\end{enumerate}

$d$ 円を年利率 $r$ の1年ごとの複利で借り入れ，1年後から毎年 $p$ 円ずつ返済する．
\begin{enumerate}
  \item $n$ 年後の借入残高を $d,p,r,n$ で表せ．
  \item 200万円を年利率5\%で借り入れ，毎年20万円ずつ返済するとき，返済が終わるのは何年後か．ただし $\log_{10}2=0.3010$，$\log_{10}3=0.4771$，$\log_{10}7=0.8451$ とする．
\end{enumerate}

\begin{enumerate}
  \item $\displaystyle\sum_{k=1}^{10}\frac3{(k+1)(k+4)}$ を求めよ．
  \item $\displaystyle\sum_{k=8}^{80}\frac1{\sqrt k+\sqrt{k+1}}$ を求めよ．
  \item $\displaystyle\sum_{n=1}^{26}\log_3\frac{n^5}{(n+1)^5}$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $\displaystyle\sum_{k=1}^nk(k+1)(k+2)=\frac{n(n+1)(n+2)(n+3)}4$ を数学的帰納法で示せ．
  \item $(k+1)^5-k^5=5k^4+10k^3+10k^2+5k+1$ を利用して，$\displaystyle\sum_{k=1}^nk^4=\frac{n(n+1)(2n+1)(3n^2+3n-1)}{30}$ を示せ．
\end{enumerate}

数列 $\{a_n\}$ の和 $S_n$ が $a_n=3n^2-S_n$ をみたす．$b_n=a_{n+1}-a_n$ とする．
\begin{enumerate}
  \item $a_1,a_2$ を求め，$a_{n+1}$ を $a_n$ と $n$ で表せ．
  \item $\{b_n\}$，$\{a_n\}$ の一般項を求めよ．
  \item $S_n>1000$ をみたす最小の $n$ を求めよ．
\end{enumerate}

$a_1=b_1=1$，$a_{n+1}=a_n+4b_n$，$b_{n+1}=a_n+b_n$ とする．
\begin{enumerate}
  \item $a_{n+1}+xb_{n+1}=y(a_n+xb_n)$ をみたす $(x,y)$ を2組求めよ．
  \item $a_n,b_n$ の一般項を求めよ．
\end{enumerate}

$a_1=2$，$a_{n+1}=\dfrac{4a_n+3}{a_n+2}$ で定まる数列を考え，$b_n=\dfrac{a_n-3}{a_n+1}$ とおく．
\begin{enumerate}
  \item $b_{n+1}$ を $b_n$ で表せ．
  \item $\{b_n\}$，$\{a_n\}$ の一般項を求めよ．
\end{enumerate}

$a_1=1$，$a_{n+1}=(n+1)a_n+n\cdot(n+1)!$ とする．
\begin{enumerate}
  \item $b_n=\dfrac{a_n}{n!}$ のみたす漸化式を求め，$\{a_n\}$ の一般項を求めよ．
  \item $\displaystyle\sum_{k=1}^n\frac{a_k}{(k-1)!}$ を求めよ．
\end{enumerate}

正の数列 $\{a_n\}$ が $a_1=3$，$a_n\,a_{n+1}^2=a_{n+1}+(n+3)(n^2+5n+5)$ をみたす．
\begin{enumerate}
  \item $a_2,a_3$ を求めよ．
  \item 一般項を推測し，数学的帰納法で証明せよ．
\end{enumerate}

$a_n=[\log_2n]$ により定まる数列 $\{a_n\}$ に対して $S(n)=\displaystyle\sum_{i=1}^na_i$ とおく（$[a]$ は $a$ を超えない最大の整数）．
\begin{enumerate}
  \item $k$ を0以上の整数とするとき，$a_n=k$ を満たす $n$ の個数を求めよ．
  \item $m$ を正の整数とするとき，$S(2^m-1)$ を $m$ の式で表せ．
  \item $S(n)=2018$ となる $n$ の値を求めよ．
\end{enumerate}

数列 $\{a_n\}$ を $a_1=1,\ a_2=3,\ na_{n+2}-(2n+1)a_{n+1}+(n+1)a_n=0$ で定める．
\begin{enumerate}
  \item $c_n=a_{n+1}-a_n$ とおくとき，$\dfrac{c_{n+1}}{n+1}=\dfrac{c_n}n$ を示し，$c_n$ を求めよ．
  \item 一般項 $a_n$ を求めよ．
  \item $\displaystyle\sum_{k=1}^n\frac{k}{a_ka_{k+1}}$ を求めよ．
\end{enumerate}

0でない実数からなる数列 $\{a_n\}$ について，$S_n=\displaystyle\sum_{k=1}^na_k$ とおくとき，すべての $n$ で $(S_n)^2=\displaystyle\sum_{k=1}^n(a_k)^3$ が成り立っている．
\begin{enumerate}
  \item $(a_{n+1})^2-a_{n+1}-2S_n=0$ を示せ．
  \item $a_1,a_2,a_3$ の組をすべて求めよ．
  \item さらにすべての $a_n$ が正であるとき，$a_n=n$ を示せ．
\end{enumerate}

正の実数 $x,y$ に対して $f(x,y)=\dfrac{x+y}2$，$g(x,y)=\dfrac{2xy}{x+y}$ と定義する．
\begin{enumerate}
  \item $x\neq y$ のとき，$g(x,y)<f(x,y)$ を示せ．
  \item $0<a_1<b_1$ とし，$a_{n+1}=g(a_n,b_n)$，$b_{n+1}=f(a_n,b_n)$ とおく．$a_{n+1}b_{n+1}=a_nb_n$ を示し，6つの数 $a_1,b_1,a_2,b_2,a_3,b_3$ を大きい順に並べよ．
  \item $b_{n+1}-a_{n+1}\leqq\dfrac12(b_n-a_n)$ を示し，$\displaystyle\lim_{n\to\infty}a_n$ を $a_1,b_1$ で表せ．
\end{enumerate}

$n$ を自然数とし，縦2，横 $n$ の長方形の盤上全体を，$1\times2$ の長方形のタイル（向きは自由）と，3マスからなるL字形のタイル（向きは自由）ですき間なく敷きつめる．その敷きつめ方の数を $a_n$ とする．また，縦2，横 $n$ の盤の右隣の列の上段に1マスを加えた盤を敷きつめる方法の数を $b_n$ とする（$a_0=1$，$b_0=0$ とする）．
\begin{enumerate}
  \item $a_1,a_2,a_3$ の値を求めよ．
  \item $a_n=a_{n-1}+a_{n-2}+2b_{n-2}$（$n\geqq2$），$b_n=a_{n-1}+b_{n-1}$（$n\geqq1$）を示せ．
