\begin{enumerate}
  \item $a_1,b_1,c_1,a_2,b_2,c_2$ を求めよ．
  \item $a_{n+1},b_{n+1},c_{n+1}$ を $a_n,b_n,c_n$ で表せ．
  \item $a_n,b_n,c_n$ を求めよ．
\end{enumerate}

太郎君は3円，花子さんは2円持っている．いま，じゃんけんをし，太郎君が勝ったならば花子さんから1円をもらえ，太郎君が負けたならば花子さんに1円を支払う．太郎君がじゃんけんに勝つ確率は $\frac23$，負ける確率は $\frac13$ であり，どちらかの所持金が0となったときにその者が敗者となりゲームは終る．$A_n$ を太郎君の所持金が $n$ 円となった時からスタートし，花子さんの所持金が0となる確率とする．
\begin{enumerate}
  \item $A_0,A_5$ の値と，$A_n$ と $A_{n+1},A_{n-1}$ の関係式（$1\leqq n\leqq4$）を求めよ．
  \item このゲームで太郎君が勝つ確率を求めよ．
  \item 太郎君の所持金が $n$ 円のときから終了までのじゃんけんの回数の期待値を $E_n$ とする．$E_3$ を求めよ．
\end{enumerate}

2つの数列 $\{a_n\},\{b_n\}$ が関係式 $\displaystyle\sum_{k=1}^n(a_k+b_k)=3^n-1+n^2$，$\displaystyle\sum_{k=1}^n(a_k-2b_k)=3^n-1-2n^2$（$n=1,2,3,\dots$）を満たすとき，
\begin{enumerate}
  \item $S_n=\sum_{k=1}^na_k$，$T_n=\sum_{k=1}^nb_k$ とするとき，$S_n$，$T_n$ を求めよ．
  \item 数列 $\{a_n\},\{b_n\}$ の一般項を求めよ．
  \item $\displaystyle\sum_{k=1}^na_kb_k$ を求めよ．
\end{enumerate}

数列 $\{a_n\}$ が $a_1=-2$，$3a_{n+1}-2a_n=1$（$n=1,2,3,\dots$）を満たしている．
\begin{enumerate}
  \item 数列 $\{a_n\}$ の一般項を求めよ．
  \item $S_n=\sum_{k=1}^na_k$ を $n$ の式で表せ．
  \item $S_n>0$ となる最小の $n$ を求めよ．
\end{enumerate}

数列 $a_1,a_2,\dots,a_n$ は，1から $2n-1$ までの $n$ 個の奇数を並べかえたものである．$S_n=\displaystyle\sum_{k=1}^n2ka_k$ とする．ただし，$n$ は3以上の整数とする．
\begin{enumerate}
  \item $\displaystyle\sum_{k=1}^n2ka_k-\sum_{k=1}^n\frac{(a_k+2k-2n-1)^2}2$ は並べ方によらないことを示し，$n$ を用いて表せ．
  \item $S_n$ を最小にする $a_k$ を $k$ を用いて表し，最小値を求めよ．
\end{enumerate}

数列 $\{x_n\}$ を $x_1=a$，$x_2=b$，$x_{n+2}=px_{n+1}+x_n$（$n=1,2,3,\dots$）で定める．ただし，$a,b,p$ は実数とする．
\begin{enumerate}
  \item すべての自然数 $n$ に対して，$x_{n+1}^2-px_nx_{n+1}-x_n^2=(-1)^{n-1}(b^2-pab-a^2)$ であることを示せ．
  \item $b^2-pab-a^2=0$，$a\neq0$ が成り立つとき，$\{x_n\}$ の一般項を $a,b$ で表せ．
  \item $p=3$，$a=1$，$b=3$ のとき，すべての $n$ について $x_n$ と $x_{n+1}$ は互いに素な整数であることを示せ．
\end{enumerate}

数列 $\{a_n\}$ を次のように定める．(i) $a_1=0$ \quad (ii) $n=2,3,4,\dots$ に対し，$a_{n-1}\geqq2n$ のとき $a_n=a_{n-1}-2n$，$a_{n-1}<2n$ のとき $a_n=a_{n-1}+2n$ とする．
\begin{enumerate}
  \item $a_7$ を求めよ．
  \item $a_k=0$ のとき，$a_{k+2j}$，$a_{k+2j+1}$ を $k,j$ で表し，条件 $m>k$，$a_m=0$ を満たす最小の整数 $m$ を $k$ で表せ．
  \item $a_{2026}$ を求めよ．
